CREATE DATABASE IF NOT EXISTS witness CHARACTER SET utf8mb4; USE witness;
DROP TEMPORARY TABLE IF EXISTS digest_vector;
CREATE TEMPORARY TABLE digest_vector (id VARCHAR(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL);
